"""Bind exact original chain identities to native mouth and surface-owner rows.

No source or output coordinates are read. The semantic planner must first
qualify the complete Bundle chain; the native graph still qualifies geometry.
"""
from numbers import Integral
from .curved_separator_member_bindings import member_chains, permission_rows


def _unique(keys, label):
    result = {}
    for index, key in enumerate(keys):
        if key in result:
            raise ValueError('Duplicate '+label+' identity')
        result[key] = index
    return result


def _rows(table, names):
    if any(name not in table for name in names):
        raise ValueError('Missing original table identity column')
    arrays = [table[name] for name in names]
    if len({len(a) for a in arrays}) != 1:
        raise ValueError('Inconsistent original table column lengths')
    if any(isinstance(value, bool) or not isinstance(value, Integral) for array in arrays for value in array):
        raise ValueError('Original table identities must be integers')
    return tuple(zip(*arrays))


def resolve(item, columns, owners, *, longitudinal_chains=False):
    """Return one declaration and its allowed side owners from scalar columns.

    ``owners`` maps an exact tuple of original junction IDs to its native patch
    leader. Mapping, corridor and port indices remain private generated IDs.
    """
    mapping = _rows(columns['Mapping'], ('st_ps_street_id','st_ps_first_section','st_ps_last_section'))
    spans = _unique(mapping, 'original span')
    corridors = _rows(columns['Corridors'], ('st_cs_span_index','st_cs_street_id','st_cs_start_index','st_cs_end_index'))
    span_corridor = _unique((row[0] for row in corridors), 'generated corridor span')
    approaches = _rows(columns['Approaches'], ('st_cj_street_id','st_cj_section_id','st_cj_reverse','st_cj_junction_id'))
    ports = _unique((row[:3] for row in approaches), 'original endpoint')
    if any(len(value) != 2 for value in (item.member_street_ids, item.member_span_ids,
                                        item.intermediate_sites, item.head_ends, item.tail_ends)):
        raise ValueError('Chained binding needs exactly two complete members')
    chains = member_chains(item, longitudinal_chains=longitudinal_chains)
    if len(set(owners.values())) != len(owners):
        raise ValueError('Original owner groups cannot share a native patch index')
    if any(isinstance(value, bool) or not isinstance(value, Integral) or not 0 <= value < 2**20
           for value in owners.values()):
        raise ValueError('Native patch indices must be bounded non-negative integers')
    groups = {}
    for sites in owners:
        for site in sites:
            if site in groups:
                raise ValueError('Original junction belongs to several surface owners')
            groups[site] = sites
    def owner(sites):
        if sites not in owners:
            raise ValueError('Chained separator lost an exact original surface owner')
        return owners[sites]
    record = dict(bundle_id=item.bundle_id, member_a=item.member_street_ids[0],
                  member_b=item.member_street_ids[1],head_patch=owner(item.head_sites),tail_patch=owner(item.tail_sites),kind=2)
    rules = []
    for side, (chain, identities, middle) in enumerate(zip(chains,item.member_span_ids,item.intermediate_sites)):
        if not identities:
            raise ValueError('Empty separator member chain')
        selected = []
        for identity in identities:
            sid = identity[0]
            if identity not in spans or spans[identity] not in span_corridor:
                raise ValueError('Chained separator lost an original generated corridor')
            row = span_corridor[spans[identity]]
            span, actual_sid, first, last = corridors[row]
            if actual_sid != sid or not 0 <= first < len(approaches) or not 0 <= last < len(approaches):
                raise ValueError('Corridor registry no longer matches the original member')
            if approaches[first][:3] != (sid,identity[1],0) or approaches[last][:3] != (sid,identity[2],1):
                raise ValueError('Corridor ports no longer match its original Section ends')
            selected.append(row);rules.append((side,1,row))
        for sites in middle:rules.append((side,0,owner(sites)))
        if set(selected) != {row for row, values in enumerate(corridors) if values[1] in chain}:
            raise ValueError('Chained declaration must cover every generated member corridor')
        for label, endpoint, row, sites in (
                ('head',item.head_ends[side],selected[0],item.head_sites),
                ('tail',item.tail_ends[side],selected[-1],item.tail_sites)):
            key = (endpoint.street_id,endpoint.section_id,endpoint.end)
            if key not in ports or endpoint.street_id != chain[0 if label == 'head' else -1]:
                raise ValueError('Chained separator lost its exact original terminal endpoint')
            port = ports[key]
            if port not in corridors[row][2:] or approaches[port][3] not in sites:
                raise ValueError('Terminal port is not on the declared end corridor and surface owner')
            record[('a_' if side==0 else 'b_')+label] = port
        # Recheck the generated tables against the declared order, not just
        # terminal membership. A stale table must not hide an internal gap.
        prefix = 'a_' if side == 0 else 'b_'
        entry = record[prefix+'head']
        if len(middle) != len(selected)-1:
            raise ValueError('Each adjacent corridor pair needs one declared intermediate owner')
        for ordinal, row in enumerate(selected):
            pair = corridors[row][2:]
            if entry not in pair:
                raise ValueError('Generated member chain is disconnected or out of order')
            leave = pair[1] if entry == pair[0] else pair[0]
            if ordinal == len(selected)-1:
                if leave != record[prefix+'tail']:
                    raise ValueError('Generated chain does not reach its declared terminal')
            else:
                junction = approaches[leave][3]
                if groups.get(junction) != middle[ordinal]:
                    raise ValueError('Generated intermediate owner differs from its declaration')
                following = [port for port in corridors[selected[ordinal+1]][2:]
                             if approaches[port][3] == junction]
                if len(following) != 1:
                    raise ValueError('Generated corridors must meet at the exact original junction')
                entry = following[0]
    rules += [(2,0,record['head_patch']),(3,0,record['tail_patch'])]
    if len(rules) > 512 or len(rules) != len(set(rules)):
        raise ValueError('Chained separator owner rules must be unique and bounded')
    if len({record[k] for k in ('a_head','a_tail','b_head','b_tail')}) != 4:
        raise ValueError('Chained separator needs four distinct terminal ports')
    if record['head_patch'] == record['tail_patch']:
        raise ValueError('Chained separator terminal owners must differ')
    return record, tuple(rules)


def bind(items, tables, label, *, longitudinal_chains=False):
    """Create private declaration/permission meshes, without changing sources."""
    from types import SimpleNamespace
    from .curved_junction_bindings import _mesh
    from .curved_patch_provider_bindings import owner_sites, values
    sites = values(tables['Junctions'],'st_cj_junction_id')
    owners = {tuple(sorted(sites[i] for i in group)):owner
              for owner,group in owner_sites({k:SimpleNamespace(data=v) for k,v in tables.items()}).items()}
    names = {'Mapping':('st_ps_street_id','st_ps_first_section','st_ps_last_section'),
             'Corridors':('st_cs_span_index','st_cs_street_id','st_cs_start_index','st_cs_end_index'),
             'Approaches':('st_cj_street_id','st_cj_section_id','st_cj_reverse','st_cj_junction_id')}
    columns = {key:{name:values(tables[key],name) for name in fields} for key,fields in names.items()}
    rows=[];rules=[]
    for item in items:
        row,allowed=resolve(item,columns,owners,longitudinal_chains=longitudinal_chains);rows.append(row)
        rules.extend(permission_rows(item.bundle_id, allowed, columns, longitudinal_chains=longitudinal_chains))
    if len({row['bundle_id'] for row in rows}) != len(rows):
        raise ValueError('Duplicate chained Bundle declaration')
    declaration = _mesh(label+' private chained separators',[(0.,0.,0.)]*len(rows),[],[
        ('st_sb_'+key,'INT','POINT',[row[key] for row in rows]) for key in
        ('bundle_id','member_a','member_b','head_patch','tail_patch','kind','a_head','a_tail','b_head','b_tail')])
    permissions = _mesh(label+' private separator side owners',[(0.,0.,0.)]*len(rules),[],[
        ('st_sr_'+key,'INT','POINT',[row[key] for row in rules]) for key in
        ('bundle_id','role','kind','owner')+(('street_id',) if longitudinal_chains else ())])
    return declaration, permissions


def bind_mixed(preparation, tables, label, *, free_chains=False, longitudinal_chains=False):
    """Retain closed/free rows and append independently checked chain records.

    Only the existing closed/free binder sets its existing sampling flags.
    Chained members keep their original sampling and complete source geometry.
    """
    if free_chains:
        from .curved_free_chain_bindings import bind_mixed as bind_free_mixed
        return bind_free_mixed(preparation, tables, label, longitudinal_chains=longitudinal_chains)
    if getattr(preparation, 'free_chained', ()):
        raise ValueError('Free-chain declarations require the free-chain asset capability')
    import bpy
    from .curved_separator_bindings import bind as bind_existing
    from .curved_junction_bindings import _mesh
    from .curved_patch_provider_bindings import values
    base = bind_existing(preparation,tables,label,free_ends=True)
    chains, permissions = bind(preparation.chained,tables,label,longitudinal_chains=longitudinal_chains)
    try:
        names = tuple(a.name for a in chains.attributes if a.name.startswith('st_sb_'))
        columns = {key:(values(base,key) if key in base.attributes else [-1]*len(base.vertices))+
                        values(chains,key) for key in names}
        ids = columns['st_sb_bundle_id']
        if len(ids) != len(set(ids)):
            raise ValueError('A Bundle cannot have several separator declaration kinds')
        return _mesh(label+' private separators',[(0.,0.,0.)]*len(ids),[],[
            (key,'INT','POINT',columns[key]) for key in names]), permissions
    finally:
        for mesh in (base,chains):
            if mesh.users == 0:bpy.data.meshes.remove(mesh)
